<h2>Calculate real estate cap rate</h2><p class="lead">Calculate capitalization rate from annual NOI and property value, or estimate value from a target cap rate.</p><div class="notice">Cap rate is an unlevered income-to-value ratio. It is not the same as mortgage rate, cash-on-cash return or total investment return.</div><div class="form-grid"><div class="field"><label for="noi">Annual net operating income (NOI)</label><input id="noi" type="number" value="600000" min="0" step="any"></div><div class="field"><label for="value">Property value / price</label><input id="value" type="number" value="7500000" min="0.01" step="any"></div><div class="field"><label for="target">Target cap rate (%)</label><input id="target" type="number" value="8" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Cap rate</span><strong id="cap">—</strong></div><div class="metric"><span>Value at target cap rate</span><strong id="implied">—</strong></div><div class="metric"><span>NOI per month</span><strong id="monthly">—</strong></div><div class="metric"><span>Value / NOI multiple</span><strong id="multiple">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('cap').textContent='—';$('implied').textContent='—';$('monthly').textContent='—';$('multiple').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const noi=num('noi'),v=num('value'),t=num('target');if(!(noi>=0&&v>0&&t>0))throw 0;const cap=noi/v*100,iv=noi/(t/100);$('cap').textContent=fmt(cap,2)+'%';$('implied').textContent=fmt(iv,2);$('monthly').textContent=fmt(noi/12,2);$('multiple').textContent=noi>0?fmt(v/noi,2)+'×':'—';$('note').textContent='Cap rate uses NOI before financing. Ensure your NOI definition is consistent and excludes debt service, income tax and capital expenditures unless your analysis intentionally differs.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
